<script setup>import AdminNavigation from '@/Components/Admin/AdminNavigation.vue';import InputError from '@/Components/InputError.vue';import PortalLayout from '@/Layouts/PortalLayout.vue';import{Head,Link,useForm}from'@inertiajs/vue3';defineProps({customers:Array});const form=useForm({customer_id:'',amount:'',currency:'NGN',payment_method:'bank_transfer',transaction_reference:'',payment_date:new Date().toISOString().slice(0,10),proof_of_payment:null,notes:''});const submit=()=>form.post(route('admin.payments.store'),{forceFormData:true});</script>
<template><Head title="Record payment"/><PortalLayout area="Administration"><template #navigation><AdminNavigation active="payments"/></template><h1 class="mb-6 text-3xl font-bold">Record manual payment</h1><form class="form-card" @submit.prevent="submit"><div class="form-grid"><label>Customer<select v-model="form.customer_id" required><option value="">Select customer</option><option v-for="customer in customers" :key="customer.id" :value="customer.id">{{ customer.customer_number }} — {{ customer.name }}</option></select><InputError :message="form.errors.customer_id"/></label><label>Amount<input v-model="form.amount" type="number" min="0.01" step="0.01" required/><InputError :message="form.errors.amount"/></label><label>Currency<input v-model="form.currency" maxlength="3" class="uppercase" required/></label><label>Payment method<select v-model="form.payment_method"><option value="bank_transfer">Bank transfer</option><option value="cash">Cash</option><option value="pos">POS</option><option value="card">Card</option><option value="other">Other</option></select></label><label>Transaction reference<input v-model="form.transaction_reference" required/><InputError :message="form.errors.transaction_reference"/></label><label>Payment date<input v-model="form.payment_date" type="date" required/></label><label>Proof of payment<input type="file" accept=".pdf,.jpg,.jpeg,.png,.webp" @change="form.proof_of_payment=$event.target.files[0]"/><InputError :message="form.errors.proof_of_payment"/></label></div><label>Notes<textarea v-model="form.notes" rows="4"/></label><div class="flex gap-3"><button class="form-button" :disabled="form.processing">Record payment</button><Link :href="route('admin.payments.index')" class="rounded-xl border px-6 py-3">Cancel</Link></div></form></PortalLayout></template>
